mapper.select:
SELECT p.user_id, SUM(p.points) AS total_points

ORDER BY total_points DESC, p.user_id ASC
LIMIT #{top}

SELECT COALESCE(MAX(ranked.position), 0)
FROM (
    SELECT p.user_id, ROW_NUMBER() OVER (ORDER BY SUM(p.points) DESC, p.user_id ASC) AS position

) ranked
WHERE ranked.user_id = #{userId}
